/* ── layout: rows from the south up, measured off the silhouette ──────────── */
// Row positions are derived from the country itself rather than hardcoded: at a
// given height the land has a width, and a row only sits where its nodes fit
// inside it. The Negev is a spike, so the bottom rows ride further north on
// their own — no magic numbers to re-tune if the outline ever changes.
function gmSpanAt(y) {
  let lo = null, hi = null;
  for (let x = 0; x <= GM_VIEW.w; x += 1) {
    if (gmInside(x, y)) { if (lo === null) lo = x; hi = x; }
  }
  return lo === null ? null : { lo, hi };
}
function gmRowPositions(count, targetY, margin, climb = 400) {
  for (let y = targetY; y > targetY - climb && y > 50; y -= 5) {
    const span = gmSpanAt(y);
    if (!span) continue;
    const lo = span.lo + margin, hi = span.hi - margin;
    if (hi - lo < (count - 1) * (margin * 2.9)) continue;
    const xs = count === 1
      ? [(lo + hi) / 2]
      : Array.from({ length: count }, (_, i) => lo + ((hi - lo) * i) / (count - 1));
    if (xs.every(x => gmInside(x, y) && gmInside(x, y - margin) && gmInside(x, y + margin))) {
      return xs.map(x => ({ x, y }));
    }
  }
  const span = gmSpanAt(targetY) || { lo: 60, hi: 240 };
  const mid = (span.lo + span.hi) / 2;
  return Array.from({ length: count }, (_, i) => ({ x: mid + (i - (count - 1) / 2) * 34, y: targetY }));
}

// The lowest line the widest row can stand on. The Negev narrows to a spike, so
// a row of three simply cannot sit at the bottom of the map; asking each row to
// climb until it fits made the first three rows pile onto the same line.
function gmWidestRow() { return Math.max(...GM_RUN.map(r => r.kind === 'shop' ? 1 : r.nodes.length)); }
function gmBottomLine(margin = 17) {
  const n = gmWidestRow();
  for (let y = 700; y > 200; y -= 5) {
    const span = gmSpanAt(y);
    if (span && span.hi - span.lo - margin * 2 >= (n - 1) * margin * 2.9) return y;
  }
  return 560;
}

// laid out once: row 0 at the bottom, the final boss at the top
let _gmLayout = null;
function gmLayout() {
  if (_gmLayout) return _gmLayout;
  const rows = GM_RUN.length;
  const TOP = 90, BOTTOM = gmBottomLine();
  const gap = (BOTTOM - TOP) / (rows - 1);
  return (_gmLayout = GM_RUN.map((row, i) => {
    const y = BOTTOM - gap * i;
    const n = row.kind === 'shop' ? 1 : row.nodes.length;
    // a row may drift a little to find land, never far enough to touch its neighbour
    return gmRowPositions(n, y, row.kind === 'shop' ? 12 : 17, gap * 0.45);
  }));
}

// flat list of the fight rows, for the summary list under the map
function gmFightRows() { return GM_RUN.filter(r => r.kind === 'fight'); }

/* ── screen ───────────────────────────────────────────────────────────────── */
// A run in progress is one that has been started, whether or not a fight has
// been fought — so the explainer shows once, not after every defeat.
function gtRunStarted(run) { return !!(run.started || run.log.length || run.picks); }

function gmIntroHTML() {
  const best = typeof gtBest === 'function' ? gtBest() : { depth: 0 };
  const office = typeof gtManagerPickerHTML === 'function' ? gtManagerPickerHTML() : '';
  // the signature-relic line is a promise, so it only appears once there is
  // actually a front office to hire from
  const sigLine = office
    ? ' קמע חתימה אחד (של המנג׳ר שבחרת) נעול איתך עד סוף המסע ולא תופס מקום.' : '';
  return `
    <div class="gt-intro">
      <div class="gt-intro-title">🗺 מסע הגאונטלט</div>
      ${best.depth ? `<p class="gt-intro-best">🏅 השיא שלך: <b>${best.depth}</b> ניצחונות${best.cleared ? ' · המסע הושלם' : ''}${best.banner ? ' · ' + gtBannerName(best.banner) : ''}</p>` : ''}
      <p>שמונה קרבות מדרום לצפון, מול סגלים אמיתיים מההיסטוריה של ליגת העל - מקבוצה שנאבקה על הישרדות ועד השושלות הגדולות ביותר בכדורגל הישראלי.</p>
      <ul class="gt-intro-list">
        <li>📜 <b>פותחים בקמע מסע</b> - אחד מששה, לכל אחד יתרון ומחיר, ומלווה אותך עד הסוף. אפשר גם בלי.</li>
        <li>🎲 <b>מגרילים קבוצה ובוחרים שחקן</b> - פעם אחת בתחילת המסע, וההרכב הזה מלווה אותך עד הסוף.</li>
        <li>⚽ <b>בכל משחק אתה בוחר את היריבה</b> מבין האפשרויות שנפתחו - ואי אפשר להתחרט.</li>
        <li>💜 <b>בכל סיבוב אחת היריבות מסומנת ELITE</b> - חזקה יותר, אבל השלל שלה מפיל קמעות הרבה יותר.</li>
        <li>🎰 <b>ניצחת? מסתובב גלגל השלל</b> - עליו גם שחקנים מהסגל שהבסת וגם <b>קמעות</b>, ואף פעם אין חובה לקחת.</li>
        <li>🛒 <b>כל 3 קרבות נפתחת חנות</b> - מטבעות מניצחונות, ועליהם ריבית.</li>
        <li>⏸ <b>מפגר במחצית?</b> אפשר לפרוק הכול על 45 הדקות הבאות - במחיר ויתור על השלל.</li>
        <li>🥇 <b>שני הבוסים האחרונים</b> משוחקים בשני משחקים - חוץ ובית, מאזן מצטבר.</li>
        <li>💀 <b>הפסד אחד מסיים את הריצה.</b></li>
        <li>🏴 <b>סיימת את כל השמונה?</b> מניפים באנר ורצים שוב - כל היריבות מתחזקות.</li>
      </ul>
      <div class="gt-intro-relic">
        <div class="gt-intro-relic-t">🔮 מה זה קמע?</div>
        <p>חפץ שמשנה כלל אחד במשחק - למשל קהל בית שמחזק אותך בקרבות מסוימים, ניצחון מובטח בפנדלים, הצצה לדירוג היריבה הבאה, או החתמת שחקן בלי הגרלה. בחירה נכונה שווה יותר משחקן טוב אחד.</p>
        <p><b>יש לך 5 מקומות לקמעות.</b> כשהם מלאים וזוכים בעוד אחד - צריך להחליט: להחליף אותו באחד מהקיימים, או לוותר עליו.${sigLine}</p>
      </div>
      ${office}
      <button class="btn-primary btn-full" id="gt-begin">יאללה, מתחילים ←</button>
    </div>`;
}

function showGauntlet() {
  showScreen('gauntlet');
  const back = document.getElementById('gauntlet-back');
  if (back) back.onclick = () => showScreen('welcome');

  const run = typeof gtRun === 'function' ? gtRun() : { at: 0, log: [], over: false };
  const map = document.getElementById('gauntlet-map');
  const note = document.getElementById('gauntlet-note');
  const reset = document.getElementById('gauntlet-reset');

  // first visit (or a fresh run): explain the mode before showing the map
  if (!gtRunStarted(run)) {
    map.innerHTML = gmIntroHTML();
    if (note) note.textContent = '';
    if (reset) reset.style.display = 'none';
    if (typeof gtWireManagerPicker === 'function') {
      gtWireManagerPicker(map, () => { run.started = true; gtSave(); showGauntlet(); });
    }
    const go = document.getElementById('gt-begin');
    if (go) go.onclick = () => {
      // with a front office in play, hiring is the first decision of the run
      if (typeof gtManagersEnabled === 'function' && gtManagersEnabled() && !run.managerId) {
        const office = map.querySelector('.gt-office');
        if (office) { office.classList.add('needed'); office.scrollIntoView({ behavior: 'smooth' }); return; }
      }
      run.started = true; gtSave(); showGauntlet();
    };
    return;
  }
  if (reset) {
    reset.style.display = '';
    reset.onclick = () => { if (typeof gtReset === 'function') gtReset(); showGauntlet(); };
  }

  // The run opens on a bargain: one run rule, or none, before the first road is
  // even on screen.
  if (typeof gtNeedsMod === 'function' && gtNeedsMod()) {
    map.innerHTML = gtModPickerHTML();
    if (note) note.textContent = '';
    if (reset) reset.style.display = 'none';   // nothing has happened yet to reset
    gtWireModPicker(map, () => showGauntlet());
    return;
  }

  // The squad has to be in memory whenever this screen draws: the shop spends it,
  // and the bar prints its rating.
  if (run.picks && typeof gtRestoreSquad === 'function') {
    gtRestoreSquad();
    if (typeof gtInvalidateDeltas === 'function') gtInvalidateDeltas();
  }

  renderGauntletMap(map, run.at, !!run.over);
  if (typeof gtWireRelicBar === 'function') gtWireRelicBar(map);
  if (typeof gtWireShop === 'function' && map.querySelector('.gt-shop')) gtWireShop(map);
  if (typeof gtWireVictory === 'function' && map.querySelector('.gt-victory')) gtWireVictory(map);
  const newRun = map.querySelector('#gt-new-run');
  if (newRun) newRun.onclick = () => { gtReset(); showGauntlet(); };

  // the sandbox, for one account
  if (typeof gtAdminHTML === 'function') {
    const panel = gtAdminHTML();
    if (panel) {
      const host = document.createElement('div');
      host.innerHTML = panel;
      map.appendChild(host);
      gtWireAdmin(host);
    }
  }

  const choose = el => {
    if (typeof gtChoose === 'function') gtChoose(+el.dataset.row, +el.dataset.node);
  };
  map.querySelectorAll('.gm-station.next[data-row]').forEach(g => g.addEventListener('click', () => choose(g)));
  map.querySelectorAll('.gm-road[data-row]').forEach(b => b.addEventListener('click', () => choose(b)));

  if (note) {
    const cleared = (run.log || []).filter(l => l.outcome === 'W').length;
    note.textContent = run.over
      ? `הריצה נגמרה אחרי ${cleared} ניצחונות.`
      : cleared ? `עברת ${cleared} מתוך 8.` : '';
  }
}
